namespace ghidra.machinelearning.functionfinding;

using docking;
using docking.action;
using docking.action;
using ghidra.app.cmd.function;
using ghidra.framework.plugintool;
using ghidra.program.model.address;
using ghidra.program.model.listing;
using ghidra.util;
using ghidra.util.table;

/**
 * A {@link DockingAction} for creating functions from rows in a {@link FunctionStartTableModel}.
 * When performed on a selection, functions are created at all rows in the selection whose 
 * {@link Interpretation} is {@link Interpretation#BLOCK_START}.
 */
public class CreateFunctionsAction : DockingAction {
	private static readonly string MENU_TEXT = "Create Function(s)";
	private static readonly string ACTION_NAME = "CreateFunctionsAction";
	private Program program;
	private FunctionStartTableModel model;
	private GhidraTable table;
	private Plugin plugin;

	/**
	 * Constructs an action for creating functions.
	 * @param plugin plugin
	 * @param program source program
	 * @param table table
	 * @param model table model
	 */
	public CreateFunctionsAction(Plugin plugin, Program program, GhidraTable table,
			FunctionStartTableModel model) : base(ACTION_NAME, plugin.getName())
    {
		this.program = program;
		this.model = model;
		this.plugin = plugin;
		this.table = table;
		init();
	}

	/* @Override */
	public bool isAddToPopup(ActionContext context) {
		return true;
	}

	/* @Override */
	public bool isEnabledForContext(ActionContext context) {
		foreach (FunctionStartRowObject row in model.getRowObjects(table.getSelectedRows())) {
			switch (row.getCurrentInterpretation()) {
				case BLOCK_START:
					return true;
				default:
					break;
			}
		}
		return false;
	}

	/* @Override */
	public void actionPerformed(ActionContext context) {
		AddressSet entries = new AddressSet();
		foreach (FunctionStartRowObject row in model.getRowObjects(table.getSelectedRows())) {
			switch (row.getCurrentInterpretation()) {
				case BLOCK_START:
					entries.add(row.getAddress());
				default:
					break;
			}
		}
		CreateFunctionCmd cmd = new CreateFunctionCmd(entries);
		plugin.getTool().executeBackgroundCommand(cmd, program);
	}

	private void init() {
		setPopupMenuData(new MenuData(new string[] { MENU_TEXT }));
		setDescription(
			string.format("Creates functions at all %s rows", Interpretation.BLOCK_START.name()));
		setHelpLocation(new HelpLocation(plugin.getName(), ACTION_NAME));
	}

}
